#!/usr/bin/env python3
"""
Round 113c (culprits), 29 September 2026. Needs round 112c.

Planted, bought or captured: plain boxes and truer places.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''

NOTE = '## Round 113c (29 September)\n\nNeeds round 112c. Tiles patch round113c_tiles.py beside it (carries 111c and\n112c\'s tiles files too).\n\n- capture_cases box (CARDS.capture, cfg.card "capture"): a plain paragraph\n  first (tiles writes it as "summary", one wording per part), then what proves\n  it and the branch, where the point is and why, the source and links; every\n  field in the fold.\n- Truer places (owner: too many cases stacked on one point). tiles capture.py:\n  refine_places moves anyone with a Wikidata record to the constituency they\n  were elected for (P768 on P39), the subnational place their office covered,\n  or where they worked; people with no office to where they worked, lived or\n  were born; the capital stays only where nothing finer is recorded.\n  place_addresses geocodes FARA principals (city, only if in the represented\n  country) and development-bank debarred firms (address) with Nominatim,\n  1,500 new lookups a run, cached in capture/geocache.json. Colombian members\n  of Congress compiled by name are matched to Wikidata where exactly one\n  Colombian citizen has that name.\n- List items that are not people (Mitrokhin\'s operations sections linked\n  HIV) are left out; Mitrokhin reads only its spies and accused sections.\n- Script version app.js bumped.\n\n'
HEAD = "## Round 113c (29 September)"

def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round113c: run from the culprits repository root")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if "## Round 112c" not in text:
        sys.exit("round113c: round 112c must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round113c: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round113c: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round113c: applied")
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("## Round 112c")
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
